'use client'

import { useEffect, useId, useRef } from 'react'
import './editorial-hero.css'

export interface EditorialHeroProps {
  eyebrow?: string
  title: string
  description?: string
  image: { src: string; alt: string }
  action?: { label: string; href: string }
  meta?: string
  className?: string
}

function nearestViewport(element: HTMLElement): HTMLElement | null {
  let parent = element.parentElement
  while (parent && parent !== document.documentElement) {
    if (/(auto|scroll|overlay)/.test(window.getComputedStyle(parent).overflowY) && parent.scrollHeight > parent.clientHeight + 1) return parent
    parent = parent.parentElement
  }
  return null
}

/** Oversized editorial typography with an image that moves at most 24px. */
export function EditorialHero({ eyebrow, title, description, image, action, meta, className = '' }: EditorialHeroProps) {
  const headingId = useId()
  const rootRef = useRef<HTMLElement>(null)

  useEffect(() => {
    const root = rootRef.current
    if (!root) return
    const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)')
    let frame = 0

    function readPosition() {
      frame = 0
      if (!root) return
      const viewport = nearestViewport(root)
      const viewportTop = viewport ? viewport.getBoundingClientRect().top + viewport.clientTop : 0
      const height = viewport?.clientHeight || window.innerHeight
      const bounds = root.getBoundingClientRect()
      const progress = Math.min(1, Math.max(0, (viewportTop + height - bounds.top) / Math.max(1, height + bounds.height)))
      const shift = reducedMotion.matches || bounds.width < 600 ? 0 : (progress - .5) * 48
      root.style.setProperty('--ac-editorial-shift', `${shift.toFixed(2)}px`)
    }

    function scheduleRead() {
      if (!frame) frame = window.requestAnimationFrame(readPosition)
    }

    document.addEventListener('scroll', scheduleRead, { capture: true, passive: true })
    window.addEventListener('scroll', scheduleRead, { passive: true })
    window.addEventListener('resize', scheduleRead)
    reducedMotion.addEventListener('change', scheduleRead)
    const resize = typeof ResizeObserver === 'undefined' ? null : new ResizeObserver(scheduleRead)
    let ancestor: HTMLElement | null = root
    while (ancestor && ancestor !== document.documentElement) {
      resize?.observe(ancestor)
      ancestor = ancestor.parentElement
    }
    readPosition()

    return () => {
      document.removeEventListener('scroll', scheduleRead, true)
      window.removeEventListener('scroll', scheduleRead)
      window.removeEventListener('resize', scheduleRead)
      reducedMotion.removeEventListener('change', scheduleRead)
      resize?.disconnect()
      window.cancelAnimationFrame(frame)
      root.style.removeProperty('--ac-editorial-shift')
    }
  }, [])

  return (
    <section ref={rootRef} className={`ac-editorial-hero ${className}`.trim()} aria-labelledby={headingId}>
      <header className="ac-editorial-topline">
        {eyebrow && <p>{eyebrow}</p>}
        {meta && <span>{meta}</span>}
      </header>
      <h2 id={headingId} className="ac-editorial-title">{title}</h2>
      <div className="ac-editorial-body">
        <div className="ac-editorial-copy">
          <span className="ac-editorial-marker" aria-hidden="true">↘</span>
          {description && <p>{description}</p>}
          {action && <a href={action.href}>{action.label}<span aria-hidden="true">↗</span></a>}
        </div>
        <figure className="ac-editorial-image">
          <img src={image.src} alt={image.alt} decoding="async" />
        </figure>
      </div>
    </section>
  )
}

.ac-editorial-hero {
  --ac-editorial-paper: #e6e5da;
  --ac-editorial-ink: #28342a;
  --ac-editorial-muted: #636d60;
  --ac-editorial-shift: 0px;
  position: relative;
  padding: clamp(24px, 5cqw, 70px);
  background: var(--ac-editorial-paper);
  color: var(--ac-editorial-ink);
  font-family: inherit;
  container-type: inline-size;
  isolation: isolate;
}

.ac-editorial-hero * { box-sizing: border-box; }

.ac-editorial-topline {
  display: flex;
  align-items: start;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: clamp(28px, 5cqw, 72px);
  padding-bottom: 15px;
  border-bottom: 1px solid color-mix(in srgb, var(--ac-editorial-ink) 22%, transparent);
  font-size: 10px;
  font-weight: 500;
  line-height: 1.5;
  letter-spacing: .08em;
  text-transform: uppercase;
}

.ac-editorial-topline p { margin: 0; }
.ac-editorial-topline > span { margin-left: auto; color: var(--ac-editorial-muted); text-align: right; }

.ac-editorial-title {
  position: relative;
  z-index: 1;
  max-width: 13ch;
  margin: 0 0 30px;
  font-family: var(--ac-editorial-heading-font, Georgia, serif);
  font-size: clamp(48px, 12cqw, 172px);
  font-weight: 400;
  line-height: .86;
  letter-spacing: -.075em;
  white-space: pre-line;
  overflow-wrap: anywhere;
}

.ac-editorial-body {
  display: grid;
  grid-template-columns: minmax(0, .8fr) minmax(0, 1.6fr);
  align-items: end;
  gap: clamp(25px, 5cqw, 80px);
}

.ac-editorial-copy { padding-bottom: 8px; }
.ac-editorial-marker { display: block; margin-bottom: 38px; font-family: sans-serif; font-size: 43px; line-height: 1; }
.ac-editorial-copy > p { max-width: 29ch; margin: 0; color: var(--ac-editorial-muted); font-size: clamp(12px, 1.3cqw, 17px); line-height: 1.6; text-wrap: pretty; }

.ac-editorial-copy > a {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  width: fit-content;
  min-width: 150px;
  min-height: 44px;
  margin-top: 23px;
  padding: 10px 0;
  border-bottom: 1px solid currentColor;
  color: inherit;
  font-size: 12px;
  line-height: 1.4;
  text-decoration: none;
}

.ac-editorial-copy > a span { font-size: 18px; transition: transform 180ms ease; }
.ac-editorial-copy > a:hover span { transform: translate(3px, -3px); }
.ac-editorial-copy > a:focus-visible { outline: 2px solid currentColor; outline-offset: 5px; }
.ac-editorial-image { position: relative; min-height: 280px; aspect-ratio: 1.22; margin: -55px 0 0; overflow: hidden; background: #b9c1b3; }
.ac-editorial-image img { position: absolute; inset: -25px 0; display: block; width: 100%; height: calc(100% + 50px); object-fit: cover; transform: translateY(var(--ac-editorial-shift)); }

@container (max-width: 600px) {
  .ac-editorial-topline { margin-bottom: 31px; font-size: 8px; }
  .ac-editorial-title { margin-bottom: 29px; font-size: clamp(43px, 13cqw, 75px); line-height: .91; }
  .ac-editorial-body { grid-template-columns: minmax(0, 1fr); gap: 24px; }
  .ac-editorial-image { grid-row: 1; min-height: 230px; margin: 0 0 0 12%; aspect-ratio: 1.15; }
  .ac-editorial-image img { transform: none; }
  .ac-editorial-copy { display: grid; grid-template-columns: 28px minmax(0, 1fr); column-gap: 17px; align-items: start; }
  .ac-editorial-marker { grid-row: 1 / 3; margin: 2px 0 0; font-size: 27px; }
  .ac-editorial-copy > p { max-width: 34ch; font-size: 12px; }
  .ac-editorial-copy > a { grid-column: 2; margin-top: 14px; font-size: 11px; }
}

@media (prefers-reduced-motion: reduce) {
  .ac-editorial-image img { transform: none; }
  .ac-editorial-copy > a span { transition: none; }
}
